/* Configurator gallery: the warm-glass preset tiles, the device-free field-well and its
 * loading shimmer, the active tile crown and the compact preset chip.
 *
 * Carved from the tail of styles.css at the gallery section so each partial stays
 * under R-5's 500-line bound. index.css imports it DIRECTLY AFTER styles.css, and each
 * block re-opens the SAME `@layer components`, so the flattened cascade is the one
 * styles.css carried whole: same layer, same source order. */
@layer components {
    /* ── The WARM-GLASS gallery tiles + the device-free field-well ────────────────
     * The tile is a `.glass-capsule` warm-glass cel
     * (composed in the SFC class list) — the §3 colourful field reads THROUGH, never
     * a flat opaque bg-card scrim. These rules add the GEOMETRY the capsule register
     * doesn't carry: the φ-tall card shape, the rounded field-well, the active ring,
     * the loading shimmer. No new material is minted — the transmissive composite is
     * the shared `.glass-capsule`; the cartoon cast is the shared `.cartoon-cast`. */

    /* The big field-well tile (the PresetPickerRow / baked-thumbnail form). A φ-tall
     * card: a 16:10 field-well crowned by a label band. The capsule register paints
     * the warm-glass body; this rule sets the card radius + the column flex so the
     * well meets the rounded crown with zero bg leak. */
    .configurator-preset-tile {
        /* `cqi`, not `vw`. The middle term of a tile clamp is a share of the ribbon the
         * tile sits in, and the ribbon is the studio — a `vw` term sized the tiles off
         * the window, so the same studio at the same width grew different tiles
         * depending on how much of the page it had been given. The floor and ceiling are
         * unmoved; only the subject of the share is corrected. */
        inline-size: clamp(160px, 22cqi, 232px);
        border-radius: var(--radius-card);
        /* The capsule fill is a warm-glass PILL by default (--radius-pill); a TILE is
         * a card, so re-point the geometry to the card radius here. The transmissive
         * fill + rim + cast all carry from .glass-capsule. */
    }

    /* The LARGE full-width TOP RIBBON tile floor. When
     * the gallery is pinned up-top (data-gallery="top") the presets span the whole studio
     * width, not the 360px aside gutter, so the tiles read one rung LARGER than the aside
     * form — the "LARGE ribbon" the aurora studio wants. Still the SAME
     * .configurator-preset-tile card (no new material, the warm-glass capsule + cast carry
     * from the base rule); only the inline-size floor lifts, and it is scoped to the top
     * placement so the aside inspector idiom stays byte-unchanged. The clamp MIN (200px)
     * clears the ≥72px LARGE-ribbon floor with headroom; the FadingScroll port (the
     * .configurator-gallery-track) still clips the horizontal overflow. */
    [data-slot="configurator"][data-gallery="top"] .configurator-preset-tile {
        inline-size: clamp(200px, 20cqi, 288px);
    }

    /* The §3 field-well — the device-free `auroraFallbackGround` background-image is
     * set inline per tile; this rule sets the cover sizing + the rounded inner crown.
     * The well is the COLOURFUL field; the warm-glass capsule frames it. */
    .configurator-preset-well {
        background-size: cover;
        background-position: center;
        /* a smooth bilinear upscale of the tiny raster (the per-quadrant mean
         * luminance is preserved — the certify band reads true). */
        image-rendering: auto;
    }

    /* The loading state — a warm shimmer until the field build lands (the field
     * build is synchronous + cheap, so this is a sub-frame flicker at most). */
    .configurator-preset-well.is-loading {
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--card) 84%, transparent) 30%,
            color-mix(in oklab, var(--foreground) 8%, var(--card)) 50%,
            color-mix(in oklab, var(--card) 84%, transparent) 70%
        );
        background-size: 200% 100%;
        animation: configurator-preset-shimmer 1.2s ease-in-out infinite;
    }
    @media (prefers-reduced-motion: reduce) {
        .configurator-preset-well.is-loading {
            animation: none;
        }
    }
}
@keyframes configurator-preset-shimmer {
    from {
        background-position: 200% 0;
    }
    to {
        background-position: -200% 0;
    }
}

/* The active tile ring — a 2px foreground-keyed inset crown over the warm-glass
 * cel (an inset ring never clips on the scroll axis, the PresetPickerRow note).
 * Composes with the capsule's own rim; the cast deepens to `-lg` in the SFC. */
@layer components {
    .configurator-preset-tile.is-active {
        box-shadow:
            /* The active-tile crown reads the house
               `--focus-ring-color` (off the shadcn `--ring`; value unchanged). */
            inset 0 0 0 2px var(--focus-ring-color),
            var(--shadow-cartoon-lg);
    }

    /* The compact CHIP form (the default fallback gallery — text-only preset pills).
     * The capsule register paints the warm-glass body; this rule restores the pill
     * radius the capsule already ships, and the active chip reads a selected fill via
     * the `--glass-capsule-fill` override hook (no fork). */
    .configurator-preset-chip {
        border-radius: var(--radius-pill);
    }
    .configurator-preset-chip.is-active {
        /* the selected rung — re-point the capsule fill toward the quiet glass-tint
         * selected register via the documented override hook (NO new composite). */
        --glass-capsule-fill: var(--glass-plate-quiet);
    }
}

